const q = $input.item.json.question || $input.item.json.body?.question || '';
if (!q) return [{ json: { error: 'Send: {"question": "your question"}' } }];
console.log('Question:', q);
return [{ json: { question: q } }];

const embedding = $input.item.json.embedding?.values;
if (!embedding) throw new Error('No embedding in input — check Get Question Embedding output');

const question = $input.item.json.question;
if (!question) throw new Error('No question in input — check Merge node');

console.log('Question:', question, '| Embedding dims:', embedding.length);
return [{ json: { question, vector: embedding, limit: 10, with_payload: true, with_vector: false } }];

const denseResult = $input.item.json.result || [];
const question = $('Dense Search via HTTP').item.json.question;
console.log('Dense search returned', denseResult.length, 'results');
if (denseResult.length > 0) {
  const top = denseResult[0];
  console.log('Top:', top.payload?.source, '>', top.payload?.section?.substring(0,30), 'score='+top.score?.toFixed(4));
}
return [{ json: { question, dense_result: denseResult } }];

// ====================================================
// BM25 + RRF Combined
// All data arrives via $input (from Scroll) - no cross-node refs needed
// ====================================================

// Get data from Qdrant scroll response
const scrollData = $input.item.json;
const allChunks = scrollData.result?.points || [];

if (allChunks.length === 0) {
  throw new Error('Qdrant is empty. Run Workflow 1 (Lab B2-1 RAG Index) first.');
}

// Get previously computed data (carried forward through nodes)
const question = $('Pass Dense Result').item.json.question;
const denseResult = $('Pass Dense Result').item.json.dense_result || [];

console.log('Corpus size:', allChunks.length, 'chunks');
console.log('Dense results:', denseResult.length);

// ---- BM25 Parameters ----
const K1 = 1.2;
const B = 0.75;
const STOP = new Set(['the','a','an','is','are','was','were','what','how','do','does',
  'of','in','to','for','on','at','with','by','and','or','not','if','it','this','that']);

// ---- Tokenize ----
function tokenize(text) {
  return text.toLowerCase().split(/[\W_]+/).filter(t => t.length >= 2 && !STOP.has(t));
}

const qTokens = tokenize(question);
const avgDocLen = allChunks.reduce((s, p) => s + (p.payload.word_count || p.payload.text.split(/\s+/).length), 0) / allChunks.length;

// ---- IDF ----
function idf(term) {
  const df = allChunks.filter(p => p.payload.text.toLowerCase().includes(term)).length;
  if (df === 0) return 0;
  return Math.log((allChunks.length - df + 0.5) / (df + 0.5) + 1);
}

// ---- BM25 per chunk ----
const bm25Scored = allChunks.map(point => {
  const docTokens = tokenize(point.payload.text);
  const docLen = docTokens.length;
  let score = 0;
  const matched = [];
  for (const term of qTokens) {
    const tf = docTokens.filter(t => t === term).length;
    if (tf === 0) continue;
    const termIdf = idf(term);
    score += termIdf * tf * (K1 + 1) / (tf + K1 * (1 - B + B * docLen / avgDocLen));
    matched.push(term);
  }
  return { source: point.payload.source, section: point.payload.section, text: point.payload.text, bm25_score: score, matched };
}).sort((a, b) => b.bm25_score - a.bm25_score);

const top10BM25 = bm25Scored.filter(r => r.bm25_score > 0).slice(0, 10);

console.log('BM25 Top 3:');
top10BM25.slice(0, 3).forEach((r, i) =>
  console.log('  [' + (i+1) + '] score=' + r.bm25_score.toFixed(3) + '  ' + r.source + ' > ' + r.section.substring(0,35) + '  terms=' + r.matched.join(','))
);

// ---- Dense ranking ----
const top10Dense = denseResult.map((r, i) => ({
  rank_dense: i + 1,
  dense_score: r.score,
  source: r.payload.source,
  section: r.payload.section,
  text: r.payload.text
}));

console.log('Dense Top 3:');
top10Dense.slice(0, 3).forEach(r =>
  console.log('  [' + r.rank_dense + '] score=' + r.dense_score.toFixed(4) + '  ' + r.source + ' > ' + r.section.substring(0,35))
);

// ---- RRF Fusion ----
const K = 60;
const rrf = {};
const meta = {};

top10Dense.forEach((r, i) => {
  const key = r.source + '||' + r.section;
  rrf[key] = (rrf[key] || 0) + 1 / (K + i + 1);
  meta[key] = { source: r.source, section: r.section, text: r.text, dense_rank: i+1, dense_score: r.dense_score };
});

top10BM25.forEach((r, i) => {
  const key = r.source + '||' + r.section;
  rrf[key] = (rrf[key] || 0) + 1 / (K + i + 1);
  if (!meta[key]) meta[key] = { source: r.source, section: r.section, text: r.text };
  meta[key].bm25_rank = i + 1;
  meta[key].bm25_score = r.bm25_score;
});

const top3 = Object.entries(rrf)
  .map(([key, score]) => ({ ...meta[key], rrf_score: score }))
  .sort((a, b) => b.rrf_score - a.rrf_score)
  .slice(0, 3);

console.log('RRF Top 3:');
top3.forEach((r, i) => {
  console.log('  [' + (i+1) + '] rrf=' + r.rrf_score.toFixed(5) + '  ' + r.source + ' > ' + r.section.substring(0,35));
  console.log('       Dense rank=' + (r.dense_rank||'-') + '  BM25 rank=' + (r.bm25_rank||'-'));
});

return [{ json: { question, top3, bm25_params: { K1, B } } }];

const { question, top3 } = $input.item.json;

let context = '';
top3.forEach((c, i) => {
  context += '[Source ' + (i+1) + '] ' + c.source + ' > ' + c.section + '\n';
  context += c.text.substring(0, 600) + '\n\n';
});

const promptText = 'You are an IT operations engineer assistant. Answer the question based ONLY on the following knowledge base excerpts. If the information is insufficient, say so explicitly.\n\nQuestion: ' + question + '\n\nKnowledge Base Excerpts:\n' + context + '\nPlease provide:\n1. Direct answer (2-3 sentences)\n2. Key steps (bullet list, max 5 points)\n3. Source reference (document > section)';

const payload = JSON.stringify({
  contents: [{ parts: [{ text: promptText }] }],
  generationConfig: { temperature: 0.1, maxOutputTokens: 1024 }
});

return [{ json: { question, top3, gemini_payload: payload } }];

const prevData = $('Build Prompt').item.json;
let answer;

try {
  answer = $input.item.json.output;
} catch(e) {
  // Fallback when no real API key
  answer = '[Gemini API Key not set]\n\nSearch results (RAG retrieval completed):\n' +
    prevData.top3.map((c, i) => (i+1) + '. ' + c.source + ' > ' + c.section + '\n   ' + c.text.substring(0,150) + '...').join('\n\n');
}

return [{ json: {
  question: prevData.question,
  answer,
  sources: prevData.top3.map(c => ({
    source: c.source,
    section: c.section,
    rrf_score: c.rrf_score.toFixed(5),
    dense_rank: c.dense_rank || null,
    bm25_rank: c.bm25_rank || null
  })),
  retrieval_strategy: 'Dense (Qdrant Cosine) + BM25 (k1=1.2, b=0.75) -> RRF (k=60)'
} }];

