const text = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const clean = text.replace(/```json\n?|```/g, '').trim();
let parsed = {};
try { parsed = JSON.parse(clean); } catch(e) { parsed = {summary: 'Parse error', description: text, priority: 'Medium'}; }
const prev = $('Parse Alert Fields').item.json;
return [{ json: {
  jira_summary:     parsed.summary     || 'Alert: ' + prev.alert_name,
  jira_description: parsed.description || prev.raw_message,
  jira_priority:    parsed.priority    || 'High',
  alert_name: prev.alert_name,
  service:    prev.service,
  severity:   prev.severity,
  host:       prev.host
} }];

return [{ json: {
  alert_name: "High CPU Usage",
  service:    "api-server",
  severity:   "critical",
  message:    "CPU usage 98% sustained for 5 minutes on prod-01",
  host:       "prod-01"
} }];

const text = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const clean = text.replace(/```json\n?|```/g, '').trim();
let parsed = {};
try { parsed = JSON.parse(clean); } catch(e) { parsed = {severity:'Medium', root_cause:'Parse error', actions: text}; }
const logText = $input.item.json.log_text || '';
return [{ json: {
  severity:    parsed.severity   || 'Medium',
  root_cause:  parsed.root_cause || '',
  actions:     parsed.actions    || '',
  original_log: logText
} }];

return [{ json: {
  log_text: "Jun 14 05:30:01 prod-db kernel: Out of memory: Kill process 3421 (java) score 950 or sacrifice child. Total-vm:8388608kB, anon-rss:7900000kB"
} }];

// TSMC IT 維運 SOP + 網路維運文件
const docs = [
  {
    source: "Network Runbook",
    sections: [
      { section: "Chapter 1: Daily Check",
        text: "Morning check ping core devices. BGP neighbors Established. CPU below 70. No errored interfaces. Check SNMP traps overnight. Verify NTP sync on all devices." },
      { section: "Chapter 2: BGP Issues",
        text: "BGP down internet connectivity degraded. BGP High severity notify L2 immediately. show bgp summary Idle Active. TCP 179 blocked. DO NOT clear BGP session without L2 approval. Check peer IP reachability, MD5 auth mismatch, AS number." },
      { section: "Chapter 2: OSPF Issues",
        text: "OSPF neighbor down routing instability. show ip ospf neighbor. Check hello interval mismatch, area mismatch, MTU mismatch. OSPF DR/BDR election storm. Dead interval 40s default. Verify loopback reachability." },
      { section: "Chapter 3: Maintenance",
        text: "Pre-maintenance checklist change approved maintenance window rollback plan. Interface bounce shutdown 10 seconds. Never restart both core switches simultaneously. Notify NOC before maintenance. Take config backup. Test rollback path." },
      { section: "Chapter 4: Interface Errors",
        text: "CRC errors physical layer problem check cable SFP. Input errors duplex mismatch. Output drops QoS congestion. show interface counters errors. High error rate >100 pps escalate. Replace SFP if persistent errors. Check fiber connector cleanliness." },
      { section: "Chapter 4: Packet Loss",
        text: "Packet loss symptoms latency spike application timeout. ping continuous test. traceroute identify hop. QoS policy misconfiguration drops high priority. Buffer exhaustion high utilization >85%. MTU black hole path MTU discovery." },
      { section: "Chapter 5: VLAN Issues",
        text: "VLAN mismatch trunk port access port. show vlan brief show interface trunk. Native VLAN mismatch CDP syslog warning. STP topology change VLAN convergence. Verify VLAN allowed on trunk. Check 802.1Q tagging end-to-end." },
      { section: "Chapter 5: LACP Link Aggregation",
        text: "LACP port-channel down member port failure. show etherchannel summary. Min-links threshold not met. LACP PDU timeout partner system mismatch. Load balancing algorithm asymmetric traffic. Verify speed duplex match on all members." },
      { section: "Chapter 2: Bandwidth",
        text: "Bandwidth congestion slow network packet loss high utilization. Over 80% congestion risk. CRC errors physical layer problem. Top talkers netflow analysis. QoS marking reclassification." },
      { section: "Chapter 6: DNS Issues",
        text: "DNS resolution failure application connectivity. nslookup dig test. DNS server unreachable check UDP 53. Stale cache TTL issue flush resolver. DNSSEC validation failure. Split-DNS internal external zone mismatch." },
      { section: "Chapter 6: Firewall ACL",
        text: "Connectivity blocked ACL deny log. show access-list hit count. ICMP blocked troubleshooting impact. Stateful firewall asymmetric routing drops. Implicit deny at end of ACL. Temporary permit for troubleshooting requires change ticket." }
    ]
  },
  {
    source: "IT SOP",
    sections: [
      { section: "Section 2: Severity Classification",
        text: "Critical response SLA 15 minutes 4 hours. High 30 minutes 8 hours. Medium 2 hours 48 hours. Low 8 hours 5 days. CPU 95 Critical. Memory 90 High. Disk 85 Medium. BGP down Critical. OSPF instability High." },
      { section: "Section 3: Incident Response",
        text: "Critical incidents notify on-call manager via phone. High incidents notify team lead messaging. Check monitoring dashboards Grafana Zabbix. Create incident ticket immediately. Timeline documentation every 30 minutes." },
      { section: "Section 3.3: Escalation",
        text: "L1 to L2 escalate if not resolved 30 minutes. L2 to L3 Critical 2 hours escalate department head. L3 Vendor contact TAC case. Network vendor Cisco TAC 1-800-553-2447. Always have case number before escalating." },
      { section: "Section 6: High CPU",
        text: "High CPU use top htop identify process. Check expected batch job. Capture lsof strace. Check deployments. DO NOT kill process without understanding. Control plane CPU routing protocol vs data plane CPU forwarding." },
      { section: "Section 6: Memory OOM",
        text: "OOM dmesg grep OOM killer. Identify killed process restart. Memory leak gradual increase days. JVM heap misconfiguration. Network device memory OSPF large LSDB BGP full table 800MB." },
      { section: "Section 7: SNMP Monitoring",
        text: "SNMP v3 authPriv required no v1 v2c in production. OID ifOperStatus 1 up 2 down. Trap receiver redundant two servers. SNMP walk verify reachability. Community string rotation every 90 days. MIB compilation device-specific." },
      { section: "Section 8: NTP Synchronization",
        text: "NTP stratum 2 source GPS reference. show ntp status stratum offset. Offset >128ms alert. NTP authentication MD5. All devices sync to internal NTP hierarchy. Logs timestamp accuracy compliance requirement." }
    ]
  }
];

const items = [];
let id = 1;
for (const doc of docs) {
  for (const sec of doc.sections) {
    items.push({ json: { id, source: doc.source, section: sec.section,
      text: sec.text, word_count: sec.text.split(/\s+/).length } });
    id++;
  }
}
console.log('Total chunks:', items.length);
return items;

const item = $input.item.json;
if (!item.embedding?.values || item.embedding.values.length !== 768) {
  throw new Error('Invalid vector: ' + (item.embedding?.values?.length || 0) + ' dims');
}
console.log('Prepping id=' + item.id + ' ' + item.source + ' > ' + item.section);
return { json: {
  chunk_id:    item.id,
  vector:      item.embedding.values,
  source:      item.source,
  section:     item.section,
  text:        item.text,
  word_count:  item.word_count
} };

// True 路徑 — 緊急處理
return [{ json: {
  ...$input.item.json,
  action: 'ESCALATE',
  message: '🚨 Critical: ' + $json.name + ' requires immediate attention',
  timestamp: new Date().toISOString()
}}];

// False 路徑 — 一般記錄
return [{ json: {
  ...$input.item.json,
  action: 'LOG',
  message: 'ℹ️ ' + $json.name + ' logged at ' + $json.severity,
  timestamp: new Date().toISOString()
}}];

// 課堂示範用 payload（模擬 critical 告警）
return [{ json: {
  name:     "HighCPU",
  severity: "critical",
  source:   "monitoring-agent"
} }];

const input = $input.item.json.body || $input.item.json;
if (!input.required_field) {
  throw new Error('Missing required_field in payload');
}
return [{ json: { status: 'ok', processed: input.required_field, timestamp: new Date().toISOString() } }];

const errMsg = $input.item.json.error || 'Unknown error';
console.log('Error caught:', errMsg);
return [{ json: {
  result:     'error',
  error_msg:  errMsg,
  timestamp:  new Date().toISOString(),
  suggestion: '請確認 payload 包含 required_field 欄位'
} }];

const results = $input.item.json.result || [];
const question = $('Demo Question').item.json.question;
console.log('Question:', question);
results.forEach((r, i) => {
  console.log(`[${i+1}] score=${r.score.toFixed(4)} ${r.payload.source} > ${r.payload.section}`);
  console.log(`     ${r.payload.text.slice(0,60)}...`);
});
return [{ json: { question, top3: results.map(r => ({
  score: r.score.toFixed(4),
  source: r.payload.source,
  section: r.payload.section,
  text: r.payload.text
})) }}];

// 模擬從 API 拿到的設備清單（多筆 items）
return [
  { json: { host: 'core-sw-01', cpu: 92, memory: 78, status: 'critical', region: 'fab-12' } },
  { json: { host: 'core-sw-02', cpu: 45, memory: 60, status: 'ok',       region: 'fab-12' } },
  { json: { host: 'dist-sw-03', cpu: 78, memory: 85, status: 'warning',  region: 'fab-14' } },
  { json: { host: 'access-01',  cpu: 23, memory: 40, status: 'ok',       region: 'fab-14' } },
  { json: { host: 'border-gw',  cpu: 88, memory: 92, status: 'critical', region: 'corp'   } },
];

// $input.all() 拿到所有 items
const all = $input.all();
const critical = all.filter(item => item.json.status === 'critical');
console.log('Total:', all.length, '| Critical:', critical.length);
return critical;

// 用 reduce 把多筆 items 聚合成一筆報表
const all = $input.all();
const byRegion = all.reduce((acc, item) => {
  const r = item.json.region;
  if (!acc[r]) acc[r] = { region: r, total: 0, critical: 0, avgCpu: 0, cpuSum: 0 };
  acc[r].total++;
  acc[r].cpuSum += item.json.cpu;
  if (item.json.status === 'critical') acc[r].critical++;
  return acc;
}, {});

return Object.values(byRegion).map(r => ({
  json: { ...r, avgCpu: Math.round(r.cpuSum / r.total) }
}));
